import 'dart:convert';

import 'package:google_maps_flutter/google_maps_flutter.dart';

/// Compact premium GO motorcycle marker for live delegate tracking.
///
/// The marker intentionally stays small on the map while the location screen
/// provides the interaction: it follows GPS updates, rotates with heading,
/// and exposes the map info window on tap.
class DelegateMotorcycleMarker {
  const DelegateMotorcycleMarker._();

  static BitmapDescriptor create() {
    return BitmapDescriptor.fromBytes(base64Decode(_pngBase64));
  }

  static const String _pngBase64 =
      '';
}
